fn editor()->viewer_journey::editor::Editor {
    use viewer_journey::{editor::{Editor,Action},commands::{parse,Command}};
    let mut editor=Editor::default();editor.apply(Action::Close).unwrap();
    for line in ["CPlane XY","Polyline Rectangle w-2,0,0 w-1,1,0","Select All","Extrude 1.5","Line w1.9,0,0 w1.9,0,1.5","Select Next","Nurbs Surface Revolve w1.5,0,0 w1.5,0,1","View Isometric","Select None","Fit"] {
        let Command::Editor(action)=parse(line).unwrap() else{panic!("Editor command")};editor.apply(action).unwrap();
    }editor
}
fn make_renderer(device:wgpu::Device,queue:wgpu::Queue,format:wgpu::TextureFormat)->Renderer {let editor=editor();Renderer::new(device,queue,format,&editor.scene)}
fn draw(renderer:&Renderer,view:&wgpu::TextureView) {let editor=editor();renderer.draw(view,&editor.background,&editor.camera.uniform());let rows=editor.scene.objects();assert_eq!(rows.len(),2);assert!(rows[0].cad.as_ref().unwrap().source.is_closed(0));assert!(rows[1].surface.as_ref().unwrap().source.is_closed(0));assert_eq!(editor.scene.paths().len(),1);assert_eq!(editor.scene.lines().len(),1);for row in rows{let bounds=editor.scene.selected_bounds(row.id).unwrap();let center=bounds.centre();let p=editor.camera.view_projection().transform_point(&session_rust::Point::new(center[0],center[1],center[2]));assert!(p[0].abs()<0.9&&p[1].abs()<0.9,"Both generated originals stay in view");}assert_eq!(renderer.stats()[0],2);}
fn verify_pixels(pixels:&[u8]) {let ink=pixels.chunks_exact(4).filter(|p|p[0]<220&&p[1]<220&&p[2]<220).count();assert!(ink>1000,"Actual extruded and revolved original faces: {ink}");let black=pixels.chunks_exact(4).filter(|p|p[0]<100&&p[1]<100&&p[2]<100).count();assert!(black>75,"Actual profile and original domain boundaries: {black}");let e=editor();for row in e.scene.objects(){let bounds=e.scene.selected_bounds(row.id).unwrap();let c=bounds.centre();let p=e.camera.view_projection().transform_point(&session_rust::Point::new(c[0],c[1],c[2]));let(x,y)=(((p[0]+1.)*320.)as i32,((1.-p[1])*240.)as i32);let mut covered=0;for yy in (y-25).max(0)..(y+25).min(480){for xx in (x-25).max(0)..(x+25).min(640){let i=(yy*640+xx)as usize*4;if pixels[i..i+3].iter().all(|v|*v<250){covered+=1}}}assert!(covered>200,"Each original has independent visible coverage: {covered}");}}
